function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => v !== -1 && !(Number.isInteger(v) && v >= 1 && v <= 100))) return 'Each value is -1 or an integer from 1 to 100.';
  return null;
}

