function lastVisitedIntegers(nums) {
  const seen = [];
  const ans = [];
  let streak = 0;
  for (const num of nums) {
    if (num === -1) {
      streak++;
      if (streak <= seen.length) {
        ans.push(seen[seen.length - streak]);
      } else {
        ans.push(-1);
      }
    } else {
      seen.push(num);
      streak = 0;
    }
  }
  return ans;
}

