function lastVisitedIntegers(nums) {
  const result = [];
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] !== -1) continue;
    let k = 0;
    for (let j = i; j >= 0 && nums[j] === -1; j--) k++;
    const newestFirst = nums.slice(0, i).filter(v => v !== -1).reverse();
    result.push(k <= newestFirst.length ? newestFirst[k - 1] : -1);
  }
  return result;
}

